githubEnv.run:
set -euo pipefail

case "${RELEASE_TRACK}" in
  internal) play_track="internal" ;;
  open) play_track="beta" ;;
  production) play_track="production" ;;
  *)
    echo "::error::Unknown release track: ${RELEASE_TRACK}"
    exit 1
    ;;
esac

echo "PLAY_TRACK=${play_track}" >> "${GITHUB_ENV}"
echo "Release track ${RELEASE_TRACK} uploads to the Google Play ${play_track} track."

set -euo pipefail
gh run list --repo "$GH_REPO" --workflow android-release.yml --branch main --status success --limit 100 --json displayTitle |
  node --input-type=module -e '
    import { appendFileSync, readFileSync } from "node:fs";
    const runs = JSON.parse(readFileSync(0, "utf8"));
    const release = runs.map((run) => /^Android Release (\d+\.\d+\.\d+) \(\d+\) to (?:open|production) on main$/.exec(run.displayTitle)).find(Boolean);
    if (!release) throw new Error("No successful production Android release version found");
    appendFileSync(process.env.GITHUB_ENV, `ORBIT_APP_VERSION=${release[1]}\n`);
    console.log(`Startup proof uses ${release[0]}`);
  '

with.build-args:
NODE_IMAGE=ghcr.io/thomasluizon/orbit-node-base:22-bookworm-slim
WEB_COMMIT_SHA=${{ steps.source.outputs.sha }}
NEXT_PUBLIC_GOOGLE_CLIENT_ID=${{ vars.PRODUCTION_NEXT_PUBLIC_GOOGLE_CLIENT_ID }}
NEXT_PUBLIC_APPLE_CLIENT_ID=${{ vars.PRODUCTION_NEXT_PUBLIC_APPLE_CLIENT_ID }}
NEXT_PUBLIC_VAPID_PUBLIC_KEY=${{ vars.PRODUCTION_NEXT_PUBLIC_VAPID_PUBLIC_KEY }}
NEXT_PUBLIC_EVENT_API_BASE=${{ vars.PRODUCTION_NEXT_PUBLIC_EVENT_API_BASE }}
NEXT_PUBLIC_SITE_URL=${{ vars.PRODUCTION_NEXT_PUBLIC_SITE_URL }}
NEXT_PUBLIC_TURNSTILE_SITE_KEY=${{ vars.PRODUCTION_NEXT_PUBLIC_TURNSTILE_SITE_KEY }}
NEXT_PUBLIC_SENTRY_DSN=${{ vars.PRODUCTION_NEXT_PUBLIC_SENTRY_DSN }}
NEXT_PUBLIC_PLAY_PACKAGE_NAME=org.useorbit.app
NEXT_PUBLIC_SENTRY_ENVIRONMENT=production
NEXT_PUBLIC_POSTHOG_KEY=${{ vars.PRODUCTION_NEXT_PUBLIC_POSTHOG_KEY }}
NEXT_PUBLIC_UPLOAD_BUCKET_ORIGIN=https://orbit-uploads-production-713285551626.s3.us-east-2.amazonaws.com

